package app.chobab.widget;

import android.app.Activity;
import android.appwidget.AppWidgetManager;
import android.content.ComponentName;
import android.content.Intent;
import android.os.Bundle;
import android.widget.*;
import org.json.JSONObject;

public class MainActivity extends Activity {
 Switch reminderToggle;
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==1&&(results.length==0||results[0]!=android.content.pm.PackageManager.PERMISSION_GRANTED)){if(reminderToggle!=null)reminderToggle.setChecked(false);Toast.makeText(this,"알림 권한을 허용해야 일정 알림을 받을 수 있습니다.",Toast.LENGTH_LONG).show();}}
 static final int VERTICAL = LinearLayout.VERTICAL;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(VERTICAL);root.setPadding(32,80,32,32);root.setBackgroundColor(0xfff8fafc);TextView title=new TextView(this);title.setText("온도 캘린더 위젯");title.setTextSize(24);root.addView(title);TextView help=new TextView(this);help.setText("웹앱의 연결·공유 → 안드로이드 위젯 연결에서 코드를 발급한 후 입력하세요.\n\n코드를 발급한 서비스 주소를 선택하세요.");help.setPadding(0,24,0,24);root.addView(help);Spinner sites=new Spinner(this);sites.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Api.ORIGINS));for(int i=0;i<Api.ORIGINS.length;i++)if(Api.ORIGINS[i].equals(Api.origin(this)))sites.setSelection(i);root.addView(sites);EditText code=new EditText(this);code.setSingleLine(true);code.setHint("5분 연결 코드");root.addView(code);Button connect=new Button(this);connect.setText("계정 연결");root.addView(connect);TextView result=new TextView(this);root.addView(result);Spinner modes=new Spinner(this); modes.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"다음 일정","일간","주간","월간","할 일"}));root.addView(modes);Button pin=new Button(this);pin.setText("홈 화면에 위젯 추가");root.addView(pin);pin.setOnClickListener(v->{AppWidgetManager manager=AppWidgetManager.getInstance(this);if(manager.isRequestPinAppWidgetSupported())manager.requestPinAppWidget(new ComponentName(this,CalendarWidget.PROVIDERS[modes.getSelectedItemPosition()]),null,null);else result.setText("홈 화면을 길게 누른 후 위젯 → 온도 위젯을 선택하세요.");});Switch reminders=new Switch(this);reminderToggle=reminders; reminders.setText("시작 10분 전 일정 알림"); reminders.setChecked(getSharedPreferences("widget",0).getBoolean("reminders",false));root.addView(reminders);TextView timing=new TextView(this);timing.setText("절전 상태에서는 알림이 늦을 수 있습니다. 일정 변경은 약 30분마다 확인합니다.");root.addView(timing);reminders.setOnCheckedChangeListener((button,checked)->{getSharedPreferences("widget",0).edit().putBoolean("reminders",checked).apply();if(checked&&android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},1);ReminderReceiver.periodic(this,checked);if(checked)new Thread(()->{try{ReminderReceiver.sync(this);}catch(Exception e){runOnUiThread(()->result.setText(e.getMessage()));}}).start();});Button disconnect=new Button(this);disconnect.setText("이 기기 연결 해제");root.addView(disconnect);disconnect.setOnClickListener(v->{getSharedPreferences("widget",0).edit().remove("token").apply();reminders.setChecked(false);ReminderReceiver.periodic(this,false);CalendarWidget.refresh(this);result.setText("기기에서 연결 정보를 지웠습니다. 웹앱에서 ‘위젯 연결 모두 해제’하면 서버 접근 권한도 폐기됩니다.");});connect.setOnClickListener(v->{String token=code.getText().toString().trim(),origin=sites.getSelectedItem().toString();if(token.length()<16){result.setText("연결 코드를 입력해주세요.");return;}connect.setEnabled(false);new Thread(()->{String message;try{JSONObject response=Api.call(origin,"claim","",new JSONObject().put("token",token));ReminderReceiver.cancel(this);Api.save(this,origin,response.getString("token"));CalendarWidget.refresh(this);try{ReminderReceiver.sync(this);}catch(Exception ignored){}message="연결했습니다. 홈 화면에 위젯을 추가하세요.";}catch(Exception e){message=e.getMessage();}String finalMessage=message;runOnUiThread(()->{result.setText(finalMessage);connect.setEnabled(true);code.setText("");});}).start();});ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);}
}
